// Initialize processing session and track all files
const folderName = $node["Google Drive Trigger"].json.name;
const folderId = $node["Google Drive Trigger"].json.id;
const response = $input.first().json;

console.log('🔍 RAW API RESPONSE DEBUG:');
console.log('Response type:', typeof response);
console.log('Response keys:', response ? Object.keys(response) : 'null');
console.log('Response structure:', JSON.stringify(response, null, 2));

// Safely get files array with proper error handling
const files = (response && response.files) ? response.files : [];

console.log('📂 FILES EXTRACTION DEBUG:');
console.log('Files found:', files ? files.length : 0);
console.log('Files type:', typeof files);
console.log('Is array:', Array.isArray(files));

if (!files || !Array.isArray(files) || files.length === 0) {
  console.log('❌ No PDF files found in the new folder');
  console.log('📊 DEBUG INFO:');
  console.log('- Folder Name:', folderName);
  console.log('- Folder ID:', folderId);
  console.log('- Response received:', JSON.stringify(response, null, 2));
  console.log('- Files variable:', files);

  return [{
    json: {
      error: 'No PDF files found',
      response_received: response,
      processing_status: 'no_files_found',
      debug_info: {
        folder_name: folderName,
        folder_id: folderId,
        response_type: typeof response,
        response_keys: response ? Object.keys(response) : null,
        files_type: typeof files,
        files_is_array: Array.isArray(files)
      }
    }
  }];
}

// Extract company name from folder name
let companyName = folderName || 'Unknown_Company';
companyName = companyName
  .replace(/^(new folder|folder|untitled|document)$/i, 'Unknown_Company')
  .replace(/[_-]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

if (companyName.length < 2 || /^(new|folder|doc|file|temp|test)$/i.test(companyName)) {
  companyName = 'Unknown_Company';
}

// Generate processing session ID
const sessionId = `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

console.log(`🚀 Starting RAG processing session: ${sessionId}`);
console.log(`📁 Folder: ${folderName}`);
console.log(`🏢 Company: ${companyName}`);
console.log(`📄 Found ${files.length} PDF files to process`);
console.log(`📋 Files details:`, files.map(f => ({ name: f.name, id: f.id, size: f.size })));

// Calculate total expected pages (estimate)
const totalExpectedSize = files.reduce((sum, file) => sum + parseInt(file.size || 0), 0);
const estimatedPages = Math.ceil(totalExpectedSize / 50000); // Rough estimate: 50KB per page

return [{
  json: {
    session_id: sessionId,
    company_name: companyName,
    folder_id: folderId,
    original_folder_name: folderName,
    total_files: files.length,
    files_to_process: files,
    processed_files: [],
    failed_files: [],
    current_file_index: 0,
    total_estimated_pages: estimatedPages,
    total_size_bytes: totalExpectedSize,
    processing_status: 'initialized',
    start_time: new Date().toISOString()
  }
}];

// Get next file to process and check if all files are done
const session = $input.first().json;

// Handle error cases
if (session.processing_status === 'no_files_found') {
  console.log('❌ No files found to process');
  return [{
    json: {
      ...session,
      processing_status: 'error_no_files',
      error_message: 'No PDF files found in the folder'
    }
  }];
}

// Ensure files_to_process exists and is an array
if (!session.files_to_process || !Array.isArray(session.files_to_process)) {
  console.log('❌ Invalid files_to_process array');
  console.log('Session received:', JSON.stringify(session, null, 2));
  return [{
    json: {
      ...session,
      processing_status: 'error_invalid_files',
      error_message: 'Invalid or missing files_to_process array',
      debug_info: {
        has_files_to_process: !!session.files_to_process,
        files_to_process_type: typeof session.files_to_process,
        is_array: Array.isArray(session.files_to_process)
      }
    }
  }];
}

// Check if we have more files to process
if (session.current_file_index >= session.files_to_process.length) {
  console.log('✅ All files processed, proceeding to validation');
  return [{
    json: {
      ...session,
      processing_status: 'all_files_processed',
      completed_time: new Date().toISOString()
    }
  }];
}

// Get current file to process
const currentFile = session.files_to_process[session.current_file_index];

// Validate current file exists
if (!currentFile) {
  console.log('❌ Current file is undefined at index:', session.current_file_index);
  return [{
    json: {
      ...session,
      processing_status: 'error_missing_file',
      error_message: `File at index ${session.current_file_index} is undefined`
    }
  }];
}

console.log(`📄 Processing file ${session.current_file_index + 1}/${session.files_to_process.length}: ${currentFile.name || 'Unknown'}`);

return [{
  json: {
    ...session,
    current_file: {
      id: currentFile.id || '',
      name: currentFile.name || 'Unknown',
      size: currentFile.size || 0,
      mimeType: currentFile.mimeType || 'application/pdf',
      index: session.current_file_index
    },
    processing_status: 'processing_file'
  }
}];

// Process extracted PDF text and prepare for vector storage
const extractedData = $input.first().json;
const session = $node["Get Next File"].json;
const currentFile = session.current_file;

// Get the extracted text
let fullText = '';
if (extractedData && extractedData.data) {
  fullText = extractedData.data;
} else if (typeof extractedData === 'string') {
  fullText = extractedData;
}

if (!fullText || fullText.length < 100) {
  console.error(`PDF text extraction failed for ${currentFile.name}`);
  return {
    json: {
      ...session,
      error: 'Text extraction failed',
      file_name: currentFile.name,
      processing_status: 'file_failed'
    }
  };
}

// Count actual pages from extracted text (rough estimate based on content)
const estimatedPages = Math.max(1, Math.ceil(fullText.length / 2000)); // ~2000 chars per page

console.log(`📄 Extracted ${fullText.length} characters (~${estimatedPages} pages) from ${currentFile.name}`);

// Split text into chunks for better vector storage
const chunkSize = 1000; // characters per chunk
const overlap = 200; // overlap between chunks
const chunks = [];

for (let i = 0; i < fullText.length; i += (chunkSize - overlap)) {
  const chunk = fullText.substring(i, i + chunkSize);
  if (chunk.trim().length > 50) { // Only include meaningful chunks
    chunks.push({
      content: chunk.trim(),
      metadata: {
        session_id: session.session_id,
        file_name: currentFile.name,
        company_name: session.company_name,
        file_id: currentFile.id,
        folder_id: session.folder_id,
        chunk_index: chunks.length,
        total_chunks_this_file: Math.ceil(fullText.length / (chunkSize - overlap)),
        file_index: currentFile.index,
        total_files: session.total_files,
        actual_pages: estimatedPages,
        extracted_at: new Date().toISOString()
      }
    });
  }
}

console.log(`📦 Created ${chunks.length} text chunks for vector storage`);

// Add file processing metadata to session
const updatedSession = {
  ...session,
  current_file_chunks: chunks.length,
  current_file_pages: estimatedPages,
  current_file_characters: fullText.length,
  processing_status: 'chunks_created'
};

// Return all chunks as separate items, each containing session info
return chunks.map(chunk => ({
  json: {
    pageContent: chunk.content,
    metadata: chunk.metadata,
    session_info: updatedSession
  }
}));

// Aggregate all chunks and check if file processing is complete
const allInputs = $input.all();

if (!allInputs || allInputs.length === 0) {
  console.log('❌ No chunks received');
  return {
    json: {
      error: 'No chunks to process',
      processing_status: 'error'
    }
  };
}

// Get the session info from the last chunk (they all have the same session info)
const lastInput = allInputs[allInputs.length - 1];

// Safely extract session info and metadata
if (!lastInput || !lastInput.json) {
  console.log('❌ Invalid input data structure');
  return {
    json: {
      error: 'Invalid input data',
      processing_status: 'error'
    }
  };
}

const sessionInfo = lastInput.json.session_info;
const lastMetadata = lastInput.json.metadata;

if (!sessionInfo || !lastMetadata) {
  console.log('❌ Missing session info or metadata');
  return {
    json: {
      error: 'Missing session info or metadata',
      processing_status: 'error',
      received_data: {
        has_session_info: !!sessionInfo,
        has_metadata: !!lastMetadata,
        input_structure: Object.keys(lastInput.json || {})
      }
    }
  };
}

console.log(`📦 Received ${allInputs.length} chunks for processing`);
console.log(`📄 File: ${lastMetadata.file_name}`);
console.log(`🔢 Expected chunks: ${lastMetadata.total_chunks_this_file}`);

// Verify we have all chunks for this file
if (allInputs.length >= lastMetadata.total_chunks_this_file) {
  console.log(`✅ All ${allInputs.length} chunks processed for ${lastMetadata.file_name}`);

  // File is complete, update session
  const updatedSession = {
    ...sessionInfo,
    current_file_index: sessionInfo.current_file_index + 1,
    processed_files: [
      ...(sessionInfo.processed_files || []),
      {
        file_name: lastMetadata.file_name,
        file_id: lastMetadata.file_id,
        chunks_created: allInputs.length,
        pages_processed: lastMetadata.actual_pages,
        characters: sessionInfo.current_file_characters,
        completed_at: new Date().toISOString()
      }
    ],
    total_chunks_processed: (sessionInfo.total_chunks_processed || 0) + allInputs.length,
    total_pages_processed: (sessionInfo.total_pages_processed || 0) + lastMetadata.actual_pages,
    processing_status: 'file_completed'
  };

  return {
    json: updatedSession
  };
} else {
  console.log(`⏳ Still processing: ${allInputs.length}/${lastMetadata.total_chunks_this_file} chunks`);

  // Return current status - chunks still processing
  return {
    json: {
      ...sessionInfo,
      processing_status: 'chunks_in_progress',
      chunks_completed: allInputs.length,
      chunks_expected: lastMetadata.total_chunks_this_file,
      current_file_name: lastMetadata.file_name
    }
  };
}

// Check if all files are processed, if not loop back to next file
const session = $input.first().json;

console.log('🔍 CHECK PROCESSING STATUS DEBUG:');
console.log('Current processing status:', session.processing_status);
console.log('Current file index:', session.current_file_index);
console.log('Total files to process:', session.files_to_process ? session.files_to_process.length : 'undefined');
console.log('Files processed so far:', session.processed_files ? session.processed_files.length : 0);

// Handle error cases
if (session.processing_status && session.processing_status.startsWith('error')) {
  console.log(`❌ Error detected: ${session.error_message || 'Unknown error'}`);
  return [{
    json: {
      ...session,
      processing_status: 'failed',
      final_error: session.error_message || 'Processing failed'
    }
  }];
}

// If chunks are still in progress, wait for completion
if (session.processing_status === 'chunks_in_progress') {
  console.log(`⏳ Waiting for chunks to complete: ${session.chunks_completed}/${session.chunks_expected}`);
  return [{
    json: {
      ...session,
      processing_status: 'waiting_for_chunks'
    }
  }];
}

// Ensure we have the files_to_process array
if (!session.files_to_process || !Array.isArray(session.files_to_process)) {
  console.log('❌ Missing or invalid files_to_process array');
  return [{
    json: {
      ...session,
      processing_status: 'error_invalid_session',
      error_message: 'Session data is corrupted or invalid'
    }
  }];
}

// Check if we need to process more files
if (session.current_file_index >= session.files_to_process.length) {
  // All files processed, proceed to validation
  console.log('🎯 All files processed! Proceeding to validation phase...');
  return [{
    json: {
      ...session,
      processing_status: 'ready_for_validation',
      processing_completed_at: new Date().toISOString()
    }
  }];
} else {
  // More files to process, loop back
  console.log(`🔄 Looping back to process file ${session.current_file_index + 1}/${session.files_to_process.length}`);
  console.log(`🔄 LOOP DEBUG: Setting status to 'continuing_loop'`);
  return [{
    json: {
      ...session,
      processing_status: 'continuing_loop'
    }
  }];
}

// Comprehensive validation of all processed files
const session = $input.first().json;

console.log('🔍 Starting comprehensive validation...');

// Validation metrics
const totalFiles = session.files_to_process.length;
const processedFiles = session.processed_files.length;
const totalChunks = session.total_chunks_processed || 0;
const totalPages = session.total_pages_processed || 0;
const failedFiles = session.failed_files ? session.failed_files.length : 0;

// Calculate success rate
const successRate = totalFiles > 0 ? (processedFiles / totalFiles * 100).toFixed(2) : 0;

// Validation checks
const validationResults = {
  files_check: {
    expected: totalFiles,
    processed: processedFiles,
    failed: failedFiles,
    success_rate: `${successRate}%`,
    status: processedFiles === totalFiles ? '✅ PASS' : '❌ FAIL'
  },
  chunks_check: {
    total_chunks: totalChunks,
    avg_chunks_per_file: totalFiles > 0 ? (totalChunks / processedFiles).toFixed(1) : 0,
    status: totalChunks > 0 ? '✅ PASS' : '❌ FAIL'
  },
  pages_check: {
    total_pages: totalPages,
    avg_pages_per_file: totalFiles > 0 ? (totalPages / processedFiles).toFixed(1) : 0,
    status: totalPages > 0 ? '✅ PASS' : '❌ FAIL'
  },
  data_integrity: {
    company_consistency: session.company_name ? '✅ PASS' : '❌ FAIL',
    session_tracking: session.session_id ? '✅ PASS' : '❌ FAIL',
    timestamp_tracking: session.start_time && session.processing_completed_at ? '✅ PASS' : '❌ FAIL'
  }
};

// Overall validation status
const allChecks = [
  validationResults.files_check.status.includes('✅'),
  validationResults.chunks_check.status.includes('✅'),
  validationResults.pages_check.status.includes('✅'),
  validationResults.data_integrity.company_consistency.includes('✅'),
  validationResults.data_integrity.session_tracking.includes('✅'),
  validationResults.data_integrity.timestamp_tracking.includes('✅')
];

const overallStatus = allChecks.every(check => check === true);

console.log('📊 VALIDATION RESULTS:');
console.log(`Files: ${validationResults.files_check.status} (${processedFiles}/${totalFiles})`);
console.log(`Chunks: ${validationResults.chunks_check.status} (${totalChunks} total)`);
console.log(`Pages: ${validationResults.pages_check.status} (${totalPages} total)`);
console.log(`Overall: ${overallStatus ? '✅ VALIDATION PASSED' : '❌ VALIDATION FAILED'}`);

return {
  json: {
    ...session,
    validation_results: validationResults,
    validation_status: overallStatus ? 'passed' : 'failed',
    validation_completed_at: new Date().toISOString(),
    processing_status: overallStatus ? 'validation_passed' : 'validation_failed',
    ready_for_approval: overallStatus
  }
};

// Final approval and completion summary
const session = $input.first().json;
const validation = session.validation_results;

if (!session.ready_for_approval) {
  console.log('❌ Processing failed validation. Manual review required.');
  return {
    json: {
      ...session,
      final_status: 'failed',
      requires_manual_review: true,
      completion_message: '❌ RAG processing failed validation checks'
    }
  };
}

// Processing approved!
const processingTime = new Date(session.processing_completed_at) - new Date(session.start_time);
const processingTimeMinutes = (processingTime / 60000).toFixed(2);

console.log('🎉 RAG PROCESSING APPROVED AND COMPLETE!');
console.log('═'.repeat(50));
console.log(`🏢 Company: ${session.company_name}`);
console.log(`📁 Folder: ${session.original_folder_name}`);
console.log(`📄 Files Processed: ${session.processed_files.length}/${session.files_to_process.length}`);
console.log(`📦 Total Chunks: ${session.total_chunks_processed}`);
console.log(`📑 Total Pages: ${session.total_pages_processed}`);
console.log(`⏱️ Processing Time: ${processingTimeMinutes} minutes`);
console.log(`💾 Vector Store: Pinecone index 'n8n'`);
console.log(`🤖 Embedding Model: mxbai-embed-large (1024 dimensions)`);
console.log(`🔍 Ready for RAG queries!`);
console.log('═'.repeat(50));

return {
  json: {
    processing_complete: true,
    final_status: 'approved',
    session_id: session.session_id,
    company_processed: session.company_name,
    summary: {
      files_processed: `${session.processed_files.length}/${session.files_to_process.length}`,
      total_chunks: session.total_chunks_processed,
      total_pages: session.total_pages_processed,
      processing_time_minutes: processingTimeMinutes,
      success_rate: validation.files_check.success_rate
    },
    technical_details: {
      pinecone_index: 'n8n',
      embedding_model: 'mxbai-embed-large',
      embedding_dimensions: 1024,
      chunk_size: 1000,
      chunk_overlap: 200
    },
    validation_passed: true,
    ready_for_rag_queries: true,
    completed_at: new Date().toISOString(),
    status_message: '🎉 RAG processing approved and ready for queries!'
  }
};
